// scripts/bundle-font-decoder.js
// Bundles opentype.js + font-decoder.js into a single file for content script injection.
// Content scripts loaded via manifest.json "js" array cannot use ES/CommonJS modules.

const fs = require('fs');
const path = require('path');

const opentypePath = 'node_modules/opentype.js/dist/opentype.min.js';
if (!fs.existsSync(opentypePath)) {
  console.error('opentype.js not found. Run: npm install');
  process.exit(1);
}

const opentype = fs.readFileSync(opentypePath, 'utf8');
const fontDecoder = fs.readFileSync('src/content/font-decoder.js', 'utf8');

const bundle = `// Generated by scripts/bundle-font-decoder.js — do not edit directly.
// Source: opentype.js (npm) + font-decoder.js

console.log('[zhcp] font-decoder-bundle: loading opentype.js...');

${opentype}

console.log('[zhcp] font-decoder-bundle: opentype.js loaded, window.opentype:', typeof window.opentype, 'var opentype:', typeof opentype);

// ======== font-decoder.js ========

${fontDecoder}
`;

const outPath = 'src/content/font-decoder-bundle.js';
fs.writeFileSync(outPath, bundle);
console.log(`Bundle written to ${outPath} (${(bundle.length / 1024).toFixed(1)} KB)`);
